import{c as n,Q as i,j as e,m as t}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"Halaman Isolir","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/isolir.md","filePath":"panduan/isolir.md"}'),o={name:"panduan/isolir.md"};function r(l,a,s,d,m,h){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="halaman-isolir" tabindex="-1">Halaman Isolir <a class="header-anchor" href="#halaman-isolir" aria-label="Permalink to &quot;Halaman Isolir&quot;">​</a></h1><p>Saat pelanggan diisolir, koneksinya dialihkan ke halaman khusus yang menginformasikan alasan penonaktifan dan cara menghubungi operator.</p><hr><h2 id="konfigurasi-halaman-isolir" tabindex="-1">Konfigurasi Halaman Isolir <a class="header-anchor" href="#konfigurasi-halaman-isolir" aria-label="Permalink to &quot;Konfigurasi Halaman Isolir&quot;">​</a></h2><p>Buka router → <strong>Pengaturan → Halaman Isolir</strong></p><h3 id="konten-halaman" tabindex="-1">Konten Halaman <a class="header-anchor" href="#konten-halaman" aria-label="Permalink to &quot;Konten Halaman&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Judul</strong></td><td>Judul utama halaman, misal <code>Akses Internet Dinonaktifkan</code></td></tr><tr><td><strong>Pesan</strong></td><td>Pesan penjelas, misal <code>Layanan Anda dinonaktifkan karena tagihan belum dibayar.</code></td></tr></tbody></table><h3 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h3><p>Pilih salah satu:</p><ul><li><strong>Warna Solid</strong> — pilih warna menggunakan color picker atau masukkan kode hex</li><li><strong>Gambar (URL)</strong> — masukkan URL gambar publik sebagai background</li></ul><h3 id="logo" tabindex="-1">Logo <a class="header-anchor" href="#logo" aria-label="Permalink to &quot;Logo&quot;">​</a></h3><p>Upload logo bisnis Anda (PNG, JPG, SVG, WebP — maks 2 MB). Logo tampil di bagian atas kartu isolir.</p><h3 id="informasi-kontak" tabindex="-1">Informasi Kontak <a class="header-anchor" href="#informasi-kontak" aria-label="Permalink to &quot;Informasi Kontak&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Label Kontak</strong></td><td>Teks tombol, misal <code>Hubungi Kami</code></td></tr><tr><td><strong>Nomor / Kontak</strong></td><td>Nomor WhatsApp (otomatis dijadikan link <code>wa.me</code>)</td></tr></tbody></table><hr><h2 id="live-preview" tabindex="-1">Live Preview <a class="header-anchor" href="#live-preview" aria-label="Permalink to &quot;Live Preview&quot;">​</a></h2><p>Sisi kanan halaman konfigurasi menampilkan <strong>preview real-time</strong> tampilan halaman isolir saat Anda mengubah pengaturan.</p><hr><h2 id="url-halaman-isolir" tabindex="-1">URL Halaman Isolir <a class="header-anchor" href="#url-halaman-isolir" aria-label="Permalink to &quot;URL Halaman Isolir&quot;">​</a></h2><p>URL halaman isolir pelanggan ditampilkan di bagian bawah panel preview:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://app.eznom.com/isolir/{router-uuid}/{customer-id}</span></span></code></pre></div><p>URL ini otomatis diisi ke konfigurasi walled garden MikroTik saat pelanggan diisolir dari sistem eznom.</p><hr><h2 id="informasi-yang-tampil-ke-pelanggan" tabindex="-1">Informasi yang Tampil ke Pelanggan <a class="header-anchor" href="#informasi-yang-tampil-ke-pelanggan" aria-label="Permalink to &quot;Informasi yang Tampil ke Pelanggan&quot;">​</a></h2><p>Kartu di halaman isolir menampilkan:</p><ul><li>Logo bisnis (jika diupload)</li><li>Judul &amp; pesan</li><li>Nama dan username pelanggan (untuk memastikan pelanggan tahu akun siapa yang terkena)</li><li>Tombol kontak menuju WhatsApp operator</li></ul>',26)])])}const g=n(o,[["render",r]]);export{p as __pageData,g as default};
